/**
 * How a customer query is narrowed down.
 *
 * <p>This is what the UI hands to {@link CustomerRepository}: the backend does
 * the filtering, so the grid above it can stay lazily loaded.
 *
 * <p>A customer matches when it satisfies both halves of the filter:
 * <ul>
 * <li>every whitespace-separated term of {@code name} occurs in the customer's
 * first or last name, ignoring case and accents;
 * <li>its status is one of {@code statuses}, or no status was selected at all.
 * </ul>
 *
 * @param name     free-text name filter; blank matches every customer
 * @param statuses statuses to keep; empty keeps every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");

    /** The filter that keeps everything. */
    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    public CustomerFilter {
        name = (name == null) ? "" : name.strip();
        // EnumSet iterates in declaration order, which is the order the filter
        // appears in the URL.
        statuses = (statuses == null || statuses.isEmpty())
                ? Set.of()
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    /** A filter on the name only. */
    public static CustomerFilter byName(String name) {
        return new CustomerFilter(name, Set.of());
    }

    /** A filter on the status only. */
    public static CustomerFilter byStatus(CustomerStatus... statuses) {
        return new CustomerFilter("", Set.of(statuses));
    }

    /** Whether this filter keeps every customer. */
    public boolean isEmpty() {
        return name.isEmpty() && statuses.isEmpty();
    }

    /** The name filter split into terms, folded for comparison. */
    public List<String> terms() {
        if (name.isEmpty()) {
            return List.of();
        }
        return WHITESPACE.splitAsStream(name)
                .filter(term -> !term.isEmpty())
                .map(CustomerFilter::fold)
                .toList();
    }

    /** Whether this filter keeps the given customer. */
    public boolean matches(Customer customer) {
        return asPredicate().test(customer);
    }

    /**
     * This filter as a predicate. The terms are folded once, up front, so that
     * one query does not redo the work per row.
     */
    public Predicate<Customer> asPredicate() {
        if (isEmpty()) {
            return customer -> true;
        }
        List<String> terms = terms();
        Set<CustomerStatus> wanted = statuses;
        return customer -> matchesStatus(customer, wanted) && matchesName(customer, terms);
    }

    private static boolean matchesStatus(Customer customer, Set<CustomerStatus> wanted) {
        return wanted.isEmpty() || wanted.contains(customer.status());
    }

    private static boolean matchesName(Customer customer, List<String> terms) {
        if (terms.isEmpty()) {
            return true;
        }
        String firstName = fold(customer.firstName());
        String lastName = fold(customer.lastName());
        for (String term : terms) {
            if (!firstName.contains(term) && !lastName.contains(term)) {
