+
+/**
+ * The same view driven in a real browser, offline. Two things can only be seen
+ * here: what the address bar says, and what typing costs the backend.
+ *
+ * <p>Named {@code *IT} so that the fast browserless tests stay the ones
+ * {@code mvn test} runs; run this one with
+ * {@code mvn -o test -Dtest=CustomerListViewBrowserIT}.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserIT {
+
+    private static Playwright playwright;
+    private static Browser browser;
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    private Page page;
+
+    @BeforeAll
+    static void startBrowser() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(true));
+    }
+
+    @AfterAll
+    static void stopBrowser() {
+        if (browser != null) {
+            browser.close();
+        }
+        if (playwright != null) {
+            playwright.close();
+        }
+    }
+
+    @BeforeEach
+    void openPage() {
+        page = browser.newContext().newPage();
+        page.setDefaultTimeout(30_000);
+    }
+
+    @AfterEach
+    void closePage() {
+        if (page != null) {
+            page.close();
+        }
+    }
+
+    @Test
+    void typingNarrowsTheListAndEndsUpInTheUrl() {
+        open("/");
+        assertEquals("Showing 500 of 500", summary().textContent());
+        queryLog.clear();
+
+        int historyLength = historyLength();
+        nameField().pressSequentially("virtanen", new Locator.PressSequentiallyOptions().setDelay(40));
+
+        PlaywrightAssertions.assertThat(summary()).hasText("Showing 15 of 500");
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/\\?name=virtanen$"));
+
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing eight letters ran " + queryLog.pageQueries().size() + " page queries");
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "Typing eight letters ran " + queryLog.countQueries() + " count queries");
+        assertEquals(historyLength, historyLength(),
+                "Typing must not add history entries");
+    }
+
+    @Test
+    void aFilteredListSurvivesAReload() {
+        open("/");
+        nameField().fill("makinen");
+        PlaywrightAssertions.assertThat(summary()).hasText("Showing 15 of 500");
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/\\?name=makinen$"));
+
+        page.reload();
+
+        PlaywrightAssertions.assertThat(nameField()).hasValue("makinen");
+        PlaywrightAssertions.assertThat(summary()).hasText("Showing 15 of 500");
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/\\?name=makinen$"));
+    }
+
+    @Test
+    void bothFiltersEndUpInTheUrlInDeclarationOrder() {
+        open("/");
+        nameField().fill("vir");
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/\\?name=vir$"));
+
+        selectStatus("CLOSED");
+        selectStatus("ACTIVE");
+
+        PlaywrightAssertions.assertThat(page)
+                .hasURL(Pattern.compile(".*/\\?name=vir&status=ACTIVE,CLOSED$"));
+    }
+
+    @Test
+    void clearingTheFilterLeavesNoParametersBehind() {
+        open("/?name=vir&status=ACTIVE");
+        PlaywrightAssertions.assertThat(nameField()).hasValue("vir");
+        PlaywrightAssertions.assertThat(summary()).hasText(Pattern.compile("Showing \\d+ of 500"));
+
+        nameField().fill("");
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/\\?status=ACTIVE$"));
+
+        selectStatus("ACTIVE"); // clicking a selected item again deselects it
+
+        PlaywrightAssertions.assertThat(summary()).hasText("Showing 500 of 500");
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/$"));
+    }
+
+    @Test
+    void aFilterMatchingNothingShowsAnEmptyGrid() {
+        open("/");
+        nameField().fill("nobody at all");
+
+        PlaywrightAssertions.assertThat(summary()).hasText("Showing 0 of 500");
+        assertEquals(0, page.locator("vaadin-grid tbody tr:visible").count(),
+                "The grid must show no rows");
+        assertEquals(0, ((Number) page.evaluate(
+                "() => document.querySelector('vaadin-grid').size")).intValue());
+    }
+
+    @Test
+    void theFilterInTheUrlIsShownInTheFields() {
+        open("/?name=vir&status=ACTIVE,CLOSED");
+
+        PlaywrightAssertions.assertThat(nameField()).hasValue("vir");
+        assertEquals(List.of("ACTIVE", "CLOSED"), selectedStatuses());
+        PlaywrightAssertions.assertThat(summary()).hasText(Pattern.compile("Showing \\d+ of 500"));
+        PlaywrightAssertions.assertThat(page.locator("vaadin-grid-cell-content").first()).isVisible();
+    }
+
+    private void open(String path) {
+        page.navigate("http://localhost:" + port + path);
+        PlaywrightAssertions.assertThat(summary()).hasText(Pattern.compile("Showing \\d+ of 500"));
+    }
+
+    private Locator summary() {
+        return page.locator("span").filter(new Locator.FilterOptions().setHasText(
+                Pattern.compile("^Showing \\d+ of \\d+$")));
+    }
+
+    private Locator nameField() {
+        return page.locator("vaadin-text-field input").first();
+    }
+
+    private void selectStatus(String status) {
+        page.locator("vaadin-multi-select-combo-box #toggleButton").click();
+        page.locator("vaadin-multi-select-combo-box-item").filter(
+                new Locator.FilterOptions().setHasText(status)).first().click();
+        page.keyboard().press("Escape");
+    }
+
+    @SuppressWarnings("unchecked")
+    private List<String> selectedStatuses() {
+        return (List<String>) page.evaluate(
+                "() => Array.from(document.querySelector('vaadin-multi-select-combo-box')"
+                        + ".selectedItems).map(item => item.label)");
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("() => window.history.length")).intValue();
+    }
+}
