+        _setValue(name, "virtanen");
+        MockVaadin.clientRoundtrip();
+
+        assertEquals(List.of(15, 15), queryLog.countQueries(),
+                "One filter change counts the matches for the summary and for the grid");
+        assertEquals(1, queryLog.pageQueries().size(),
+                "Applying a filter ran the page queries " + queryLog.pageQueries());
+    }
+
+    @Test
+    void sortingStillWorksWhileFiltering() {
+        _setValue(statusFilter(), Set.of(CustomerStatus.ACTIVE));
+        _sortByKey(grid(), "lastName", SortDirection.DESCENDING);
+
+        String firstDescending = row(0).get(1);
+        assertEquals("Zetterberg", firstDescending);
+
+        _sortByKey(grid(), "lastName", SortDirection.ASCENDING);
+        assertEquals("Aaltonen", row(0).get(1));
+        assertEquals(167, _size(grid()));
+        assertEquals("Showing 167 of 500", summary().getText());
+    }
+
+    // --- the URL -------------------------------------------------------------
+
+    @Test
+    void filterIsReadFromTheUrl() {
+        UI.getCurrent().navigate("", new QueryParameters(Map.of(
+                "name", List.of("vir"),
+                "status", List.of("ACTIVE,CLOSED"))));
+
+        assertEquals("vir", nameFilter().getValue());
+        assertEquals(Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED), statusFilter().getValue());
+        int matches = _size(grid());
+        assertEquals("Showing " + matches + " of 500", summary().getText());
+        for (int row = 0; row < matches; row++) {
+            List<String> cells = row(row);
+            assertTrue(cells.get(0).toLowerCase().contains("vir")
+                    || cells.get(1).toLowerCase().contains("vir"), "Unexpected row " + cells);
+            assertTrue(List.of("ACTIVE", "CLOSED").contains(cells.get(4)), "Unexpected row " + cells);
+        }
+    }
+
+    @Test
+    void noParametersMeansNoFilter() {
+        UI.getCurrent().navigate("");
+        assertEquals("", nameFilter().getValue());
+        assertEquals(Set.of(), statusFilter().getValue());
+        assertEquals(500, _size(grid()));
+    }
+
+    @Test
+    void navigatingWithoutParametersClearsTheFilter() {
+        UI.getCurrent().navigate("", QueryParameters.of("name", "vir"));
+        assertEquals("vir", nameFilter().getValue());
+
+        UI.getCurrent().navigate("");
+        assertEquals("", nameFilter().getValue());
+        assertEquals(Set.of(), statusFilter().getValue());
+        assertEquals(500, _size(grid()));
+    }
+
+    @Test
+    void statusParameterIsForgivingAboutWhatItIsGiven() {
+        UI.getCurrent().navigate("", new QueryParameters(Map.of(
+                "status", List.of("closed, MADE_UP ,active"))));
+
+        assertEquals(Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED), statusFilter().getValue());
+        assertEquals(333, _size(grid()));
+    }
+
+    @Test
+    void aBlankNameParameterFiltersNothing() {
+        UI.getCurrent().navigate("", QueryParameters.of("name", "   "));
+
+        assertEquals(500, _size(grid()));
+        assertEquals("Showing 500 of 500", summary().getText());
+    }
+
+    // --- helpers -------------------------------------------------------------
+
+    private Grid<?> grid() {
+        return _get(Grid.class);
+    }
+
+    private List<String> row(int index) {
+        return _getFormattedRow(grid(), index);
+    }
+
+    @SuppressWarnings("unchecked")
+    private TextField nameFilter() {
+        return _get(TextField.class);
+    }
+
+    @SuppressWarnings("unchecked")
+    private MultiSelectComboBox<CustomerStatus> statusFilter() {
+        return _get(MultiSelectComboBox.class);
+    }
+
+    private Span summary() {
+        return _get(Span.class);
+    }
 }
