+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertThrows;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import com.example.customers.domain.Customer;
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerRepository;
+import com.example.customers.domain.CustomerSort;
+import com.example.customers.domain.CustomerStatus;
+import com.example.customers.domain.QueryLog;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+
+/**
+ * The filter is a backend query: it pages, it sorts, and it shows up in
+ * {@link QueryLog} exactly once per query, like every other query.
+ */
+@SpringBootTest
+class CustomerRepositoryFilterTest {
+
+    @Autowired
+    private CustomerRepository repository;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @BeforeEach
+    void clearLog() {
+        queryLog.clear();
+    }
+
+    @Test
+    void aFilteredPageIsRecordedOnce() {
+        List<Customer> page = repository.findAll(0, 10, List.of(), CustomerFilter.byName("makinen"));
+
+        assertEquals(10, page.size());
+        assertEquals(List.of(new QueryLog.PageQuery(0, 10, 10)), queryLog.pageQueries());
+        assertEquals(List.of(), queryLog.countQueries());
+    }
+
+    @Test
+    void aFilteredCountIsRecordedOnce() {
+        assertEquals(15, repository.count(CustomerFilter.byName("makinen")));
+        assertEquals(List.of(15), queryLog.countQueries());
+        assertEquals(List.of(), queryLog.pageQueries());
+    }
+
+    @Test
+    void anUnfilteredQueryIsStillRecordedOnce() {
+        repository.findAll(0, 5, List.of());
+        repository.count();
+
+        assertEquals(List.of(new QueryLog.PageQuery(0, 5, 5)), queryLog.pageQueries());
+        assertEquals(List.of(500), queryLog.countQueries());
+    }
+
+    @Test
+    void theFilterStillRefusesToServeMoreThanOnePage() {
+        assertThrows(IllegalArgumentException.class, () -> repository.findAll(
+                0, CustomerRepository.MAX_PAGE_SIZE + 1, List.of(), CustomerFilter.EMPTY));
+    }
+
+    @Test
+    void pagingAndSortingApplyToTheMatchesOnly() {
+        CustomerFilter filter = new CustomerFilter("a", Set.of(CustomerStatus.PENDING));
+        List<CustomerSort> byLastName = List.of(new CustomerSort("lastName", true));
+
+        int matches = repository.count(filter);
+        assertTrue(matches > 20, "Expected a filter with plenty of matches, got " + matches);
+
+        List<Customer> firstPage = repository.findAll(0, 10, byLastName, filter);
+        List<Customer> secondPage = repository.findAll(10, 10, byLastName, filter);
+        List<Customer> both = repository.findAll(0, 20, byLastName, filter);
+
+        assertEquals(both, concat(firstPage, secondPage), "The pages must be pages of one sorted result");
+        assertTrue(both.stream().allMatch(filter::matches), "Every row must match the filter");
+        assertTrue(isSortedByLastName(both), "The backend must do the sorting: " + both);
+    }
+
+    @Test
+    void everyTermMustMatchButEitherNameWillDo() {
+        assertEquals(2, repository.count(CustomerFilter.byName("ada aal")));
+        assertEquals(2, repository.count(CustomerFilter.byName("aal ada")));
+        assertEquals(0, repository.count(CustomerFilter.byName("ada virtanen")));
+        assertEquals(500, repository.count(CustomerFilter.byName("   ")));
+    }
+
+    @Test
+    void accentsAndCaseAreIgnoredInBothDirections() {
+        assertEquals(15, repository.count(CustomerFilter.byName("makinen")));
+        assertEquals(15, repository.count(CustomerFilter.byName("MAKINEN")));
+        assertEquals(15, repository.count(CustomerFilter.byName("mäkinen")));
+        assertEquals(15, repository.count(CustomerFilter.byName("MÄKINEN")));
+        assertEquals(12, repository.count(CustomerFilter.byName("josephine")));
+        assertEquals(12, repository.count(CustomerFilter.byName("joséphine")));
+    }
+
+    @Test
+    void noSelectedStatusMeansEveryStatus() {
+        assertEquals(500, repository.count(CustomerFilter.byStatus()));
+        assertEquals(167, repository.count(CustomerFilter.byStatus(CustomerStatus.ACTIVE)));
+        assertEquals(333, repository.count(
+                CustomerFilter.byStatus(CustomerStatus.ACTIVE, CustomerStatus.CLOSED)));
+        assertEquals(500, repository.count(CustomerFilter.byStatus(CustomerStatus.values())));
+    }
+
+    private static List<Customer> concat(List<Customer> first, List<Customer> second) {
+        return java.util.stream.Stream.concat(first.stream(), second.stream()).toList();
+    }
+
+    private static boolean isSortedByLastName(List<Customer> customers) {
+        for (int i = 1; i < customers.size(); i++) {
+            if (customers.get(i - 1).lastName().compareToIgnoreCase(customers.get(i).lastName()) > 0) {
+                return false;
+            }
+        }
+        return true;
+    }
+}
